t_radius': 'medium'}], 'dependencies': [{'from_task': 'detect_drift', 'to_task': 'classify_drift', 'kind': 'hard', 'reason': ''}, {'from_task': 'classify_drift', 'to_task': 'auto_remediate', 'kind': 'hard', 'reason': ''}, {'from_task': 'auto_remediate', 'to_task': 'generate_report', 'kind': 'hard', 'reason': ''}], 'branches': []}

